                    if cst + 1e-12 < best_cost:
                        best = cand
                        best_cost = cst
                        changed = True
                        break
                if changed:
                    break
        return best

    for idx in range(len(routes)):
        routes[idx] = two_opt(routes[idx])
        # choose orientation if better
        rev = routes[idx][::-1]
        if route_cost(rev) < route_cost(routes[idx]):
            routes[idx] = rev

    # -------------------- final cleanup: ensure every customer exactly once --------------------
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    duplicates = [c for c in customers if seen.get(c, 0) > 1]

    # remove duplicates from later occurrences
    if duplicates:
        count = {}
        new_routes = []
        for r in routes:
            nr = []
            load = 0
            for c in r:
                count[c] = count.get(c, 0) + 1
                if count[c] == 1:
                    nr.append(c)
                    load += demand(c)
            if nr:
                new_routes.append(nr)
        routes = new_routes

    # insert missing customers deterministically into feasible positions
    for c in missing:
        best = None
        best_key = None
        for i in range(len(routes)):
            if route_load(routes[i]) + demand(c) > cap:
                continue
            base = route_cost(routes[i])
            for pos in range(len(routes[i]) + 1):
                cand = routes[i][:pos] + [c] + routes[i][pos:]
                delta = route_cost(cand) - base
                key = (delta, i, pos)
                if best is None or key < best_key:
                    best = cand
                    best_key = key
        if best is not None:
            i = best_key[1]
            routes[i] = best
        else:
            routes.append([c])

    # sort routes by first customer id for determinism
    routes.sort(key=lambda r: (r[0] if r else -1, len(r), route_cost(r)))

    return routes
